-- Whisk Flow core schema.
-- This file is shared by the embedded local database and Supabase PostgreSQL.
-- IDs and timestamps are generated by the application for portability.

CREATE TABLE IF NOT EXISTS profiles (
  id UUID PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  full_name TEXT,
  avatar_url TEXT,
  plan TEXT NOT NULL DEFAULT 'free',
  credits INTEGER NOT NULL DEFAULT 1200 CHECK (credits >= 0),
  reserved_credits INTEGER NOT NULL DEFAULT 0 CHECK (reserved_credits >= 0),
  billing_customer_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS billing_customer_id TEXT;

CREATE TABLE IF NOT EXISTS projects (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  mode TEXT NOT NULL DEFAULT 'video',
  status TEXT NOT NULL DEFAULT 'draft',
  aspect_ratio TEXT NOT NULL DEFAULT '16:9',
  provider TEXT,
  model TEXT,
  settings JSONB NOT NULL DEFAULT '{}'::jsonb,
  prompt_history JSONB NOT NULL DEFAULT '[]'::jsonb,
  export_history JSONB NOT NULL DEFAULT '[]'::jsonb,
  cover_asset_id UUID,
  template_slug TEXT,
  is_example BOOLEAN NOT NULL DEFAULT FALSE,
  favorite BOOLEAN NOT NULL DEFAULT FALSE,
  deleted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS projects_owner_updated_idx
  ON projects(owner_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS projects_owner_deleted_idx
  ON projects(owner_id, deleted_at);
CREATE INDEX IF NOT EXISTS projects_owner_favorite_idx
  ON projects(owner_id, favorite) WHERE favorite = TRUE;

CREATE TABLE IF NOT EXISTS assets (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  project_id UUID REFERENCES projects(id) ON DELETE SET NULL,
  scene_id UUID,
  kind TEXT NOT NULL DEFAULT 'image',
  title TEXT NOT NULL DEFAULT 'Untitled asset',
  url TEXT,
  thumbnail_url TEXT,
  storage_provider TEXT NOT NULL DEFAULT 'local',
  storage_path TEXT,
  mime_type TEXT NOT NULL DEFAULT 'image/jpeg',
  size_bytes BIGINT NOT NULL DEFAULT 0,
  width INTEGER,
  height INTEGER,
  duration_seconds NUMERIC(8, 2),
  prompt TEXT,
  negative_prompt TEXT,
  provider TEXT,
  model TEXT,
  aspect_ratio TEXT,
  source TEXT NOT NULL DEFAULT 'upload',
  folder TEXT NOT NULL DEFAULT 'Unsorted',
  tags TEXT[] NOT NULL DEFAULT '{}',
  favorite BOOLEAN NOT NULL DEFAULT FALSE,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  is_example BOOLEAN NOT NULL DEFAULT FALSE,
  deleted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS assets_owner_created_idx
  ON assets(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS assets_owner_kind_idx
  ON assets(owner_id, kind);
CREATE INDEX IF NOT EXISTS assets_owner_favorite_idx
  ON assets(owner_id, favorite) WHERE favorite = TRUE;
CREATE INDEX IF NOT EXISTS assets_project_idx
  ON assets(project_id);
CREATE INDEX IF NOT EXISTS assets_owner_deleted_idx
  ON assets(owner_id, deleted_at);
CREATE INDEX IF NOT EXISTS assets_search_idx
  ON assets USING GIN (to_tsvector('english', COALESCE(title, '') || ' ' || COALESCE(prompt, '')));

CREATE TABLE IF NOT EXISTS scenes (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  title TEXT NOT NULL DEFAULT 'Untitled scene',
  prompt TEXT NOT NULL DEFAULT '',
  negative_prompt TEXT NOT NULL DEFAULT '',
  duration_seconds INTEGER NOT NULL DEFAULT 4 CHECK (duration_seconds BETWEEN 1 AND 20),
  order_index INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'draft',
  reference_asset_ids UUID[] NOT NULL DEFAULT '{}',
  first_frame_asset_id UUID,
  last_frame_asset_id UUID,
  transition TEXT NOT NULL DEFAULT 'cut',
  thumbnail_url TEXT,
  video_asset_id UUID,
  generation_job_id UUID,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS scenes_project_order_idx
  ON scenes(project_id, order_index);
CREATE INDEX IF NOT EXISTS scenes_owner_idx
  ON scenes(owner_id);

CREATE TABLE IF NOT EXISTS generation_jobs (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  project_id UUID REFERENCES projects(id) ON DELETE SET NULL,
  scene_id UUID REFERENCES scenes(id) ON DELETE SET NULL,
  kind TEXT NOT NULL,
  provider TEXT NOT NULL,
  model TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued',
  prompt TEXT NOT NULL,
  negative_prompt TEXT NOT NULL DEFAULT '',
  settings JSONB NOT NULL DEFAULT '{}'::jsonb,
  output_count INTEGER NOT NULL DEFAULT 1,
  credits_reserved INTEGER NOT NULL DEFAULT 0,
  provider_job_id TEXT,
  result_asset_id UUID,
  asset_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  error TEXT,
  attempts INTEGER NOT NULL DEFAULT 1,
  idempotency_key TEXT NOT NULL,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (owner_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS jobs_owner_created_idx
  ON generation_jobs(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS jobs_status_idx
  ON generation_jobs(status, updated_at);
CREATE INDEX IF NOT EXISTS jobs_project_idx
  ON generation_jobs(project_id);

CREATE TABLE IF NOT EXISTS credit_transactions (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  generation_id UUID REFERENCES generation_jobs(id) ON DELETE SET NULL,
  type TEXT NOT NULL,
  amount INTEGER NOT NULL DEFAULT 0,
  reserved_delta INTEGER NOT NULL DEFAULT 0,
  balance_after INTEGER NOT NULL,
  description TEXT NOT NULL,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS credit_transactions_owner_created_idx
  ON credit_transactions(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS credit_transactions_generation_idx
  ON credit_transactions(generation_id);

CREATE TABLE IF NOT EXISTS exports (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
  format TEXT NOT NULL,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS exports_project_idx ON exports(project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS billing_orders (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('subscription', 'credits')),
  plan_id TEXT NOT NULL,
  credits INTEGER NOT NULL DEFAULT 0 CHECK (credits >= 0),
  amount_cents INTEGER NOT NULL DEFAULT 0 CHECK (amount_cents >= 0),
  currency TEXT NOT NULL DEFAULT 'usd',
  billing_interval TEXT CHECK (billing_interval IN ('month', 'year')),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'paid', 'failed', 'cancelled')),
  provider TEXT NOT NULL DEFAULT 'demo',
  provider_session_id TEXT,
  provider_payment_id TEXT,
  provider_customer_id TEXT,
  idempotency_key TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  UNIQUE (owner_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS billing_orders_owner_created_idx
  ON billing_orders(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS billing_orders_session_idx
  ON billing_orders(provider_session_id);

CREATE TABLE IF NOT EXISTS billing_subscriptions (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  plan_id TEXT NOT NULL,
  billing_interval TEXT NOT NULL CHECK (billing_interval IN ('month', 'year')),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'past_due', 'cancelled', 'incomplete')),
  provider TEXT NOT NULL DEFAULT 'demo',
  provider_subscription_id TEXT UNIQUE,
  provider_customer_id TEXT,
  current_period_end TIMESTAMPTZ,
  cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS billing_subscriptions_owner_idx
  ON billing_subscriptions(owner_id, created_at DESC);

CREATE TABLE IF NOT EXISTS billing_events (
  id TEXT PRIMARY KEY,
  type TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
